    SELECT 'pendientes-rocosas-calcicolas-8210', '8210', 'Pendientes rocosas calcícolas con vegetación casmofítica', 'Roquedos', 'Paredes y cortados de roca caliza en los que la vegetación no vive sobre el suelo, sino dentro de las fisuras. Son plantas de raíz larguísima y crecimiento lentísimo, agarradas a la grieta, que aprovechan el agua que escurre por la pared. Los roquedos han quedado a salvo del arado y del ganado durante milenios, y por eso concentran una proporción altísima de especies que no existen en ningún otro lugar.', 0, 37.801226, -0.90962, '#daa520', '{"type":"Polygon","coordinates":[[[-0.922489,37.805153],[-0.922403,37.804946],[-0.922245,37.804592],[-0.922231,37.804558],[-0.922101,37.804225],[-0.922,37.803837],[-0.922102,37.803299],[-0.922118,37.802923],[-0.922421,37.802545],[-0.922364,37.802395],[-0.922296,37.802369],[-0.922104,37.802294],[-0.921801,37.802133],[-0.921599,37.802008],[-0.921571,37.801595],[-0.921442,37.801115],[-0.921154,37.800862],[-0.920736,37.800589],[-0.920433,37.800223],[-0.920231,37.79997],[-0.920029,37.799547],[-0.919799,37.799444],[-0.919308,37.799399],[-0.918918,37.799273],[-0.918572,37.799089],[-0.91826,37.798831],[-0.918246,37.798827],[-0.918163,37.798801],[-0.918035,37.798767],[-0.917788,37.798685],[-0.917445,37.7986],[-0.917184,37.79852],[-0.916818,37.798421],[-0.916561,37.79835],[-0.91634,37.79829],[-0.916035,37.798212],[-0.91589,37.798178],[-0.915795,37.798148],[-0.915681,37.798115],[-0.915535,37.798065],[-0.915429,37.798038],[-0.915353,37.798011],[-0.915263,37.797974],[-0.91522,37.797951],[-0.914843,37.797826],[-0.914744,37.797797],[-0.914689,37.797776],[-0.914644,37.797749],[-0.914312,37.797501],[-0.914234,37.797452],[-0.914184,37.79743],[-0.914046,37.79731],[-0.913481,37.796888],[-0.913464,37.796875],[-0.913105,37.796854],[-0.912441,37.796946],[-0.911747,37.797231],[-0.910924,37.797412],[-0.910376,37.797265],[-0.909914,37.797036],[-0.909525,37.797036],[-0.908976,37.797069],[-0.908355,37.797182],[-0.907763,37.797295