    SELECT 'Cornical' common_name, 'Periploca angustifolia' scientific_name, 'flora' kingdom, 'Arbusto' family, 'Matorral cálido, laderas soleadas y barrancos de clima muy seco' primary_habitat, 'Arbusto de hojas estrechas y coriáceas y flores pequeñas con cinco pétalos de un pardo verdoso y aspecto aterciopelado. Sus frutos son dos vainas largas y curvas dispuestas en forma de cuerno, de donde le viene el nombre popular de cornical. Suelta látex al romperse.' description, NULL description_source, 'Frutos en dos vainas curvas enfrentadas, como cuernos; Látex blanco al partir una hoja o rama; Flores pardo verdosas con aspecto de terciopelo' identification_tips, 'Primavera y verano (floración)' seasonality, 'https://inaturalist-open-data.s3.amazonaws.com/photos/609975159/original.jpg' image_url, 'Quentin Groom (CC0) · GBIF' image_attribution, NULL latitude, NULL longitude, 1 rarity_score, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}' rarity_basis, 4 rarity_local, '{"categoria":"Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)","ambito":"autonómico","origen":"regionalStatus del park.json"}' rarity_local_basis, 1 is_featured, 1 is_visible, NULL hidden_reason, 'GBIF: 4 ocurrencias dentro de los polígonos de hábitat del espacio (3 hábitats; barrido de 2026-08-17); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; Decreto n.º 259/2019, de 10 de octubre, Plan de gestión integral del Mar Menor y la franja litoral mediterránea, volumen II §1.1.5.2 (ZEC «Cabezo Gordo», ES6200013) (BORM n.º 242, de 19 de octubre de 2019): la norma la enumera en la ZEC «Cabezo Gordo» (ES6200013), 229,46 ha, sobre las 271,8 ha del Paisaje Protegido. El propio plan hace suyo ese inventario para el Paisaje Protegido —su §2.2.2 remite al §1.1.5 «y, por tanto, el Paisaje Protegido “Cabezo Gordo”»—, pero el perímetro inventariado es el de la ZEC, no el del espacio; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Gentianales' taxon_order, 'Apocynaceae' taxon_family, 'Periploca' taxon_genus, 'No evaluada en la Lista Roja mundial de la UICN' iucn_global, NULL iucn_spain, 'ANEXO I. 2) Lista de taxones forestales para conservación ex situ (Real Decreto 159/2022, de 1 de marzo)' spain_status, 'Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)' regional_status, 'Región de Murcia' regional_ccaa, NULL review_note, 7034 eidos_taxonid, 6022574 gbif_species_key, 4 gbif_occurrences, NULL zepa_site_code, NULL is_migratory, NULL site_presence
    UNION ALL
    SELECT 'Cosentinia vellea', 'Cosentinia vellea', 'flora', 'Helecho', 'Grietas de roquedos secos y soleados, paredones y pedregales', 'Helecho pequeño cubierto por completo de una densa lana parda que le da aspecto afieltrado y le permite sobrevivir en roca seca y al sol. En sequía se enrolla sobre sí mismo hasta parecer muerto, y se despliega en cuanto llueve.', NULL, 'Frondes cubiertas de lana parda, aspecto afieltrado; Se enrolla en verano y revive con la lluvia; En roca seca y soleada, no en umbrías húmedas', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cosentinia_vellea_kz02.jpg?width=1280', 'Krzysztof Ziarnek, Kenraiz (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (3 hábitats; barrido de 2026-08-17); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Polypodiopsida', 'Polypodiales', 'Pteridaceae', 'Cosentinia', 'No evaluada en la Lista Roja mundial de la UICN', NULL, 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 3758, 7335582, 1, NULL, NULL, NULL
    UNION ALL
    SELECT 'Jarilla', 'Helianthemum violaceum', 'flora', 'Mata', 'Tomillares y matorral raso sobre suelos calizos y margosos secos', 'Jarilla pequeña de hojas estrechas y grisáceas con el borde enrollado, que se cubre en primavera de flores amarillas efímeras. Como en todas las jarillas, los pétalos apenas duran una mañana y se renuevan cada día.', NULL, 'Hojas estrechas con el borde enrollado hacia abajo; Flores amarillas que duran solo unas horas; Mata baja y grisácea del tomillar', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Helianthemum_violaceum_habitus_SierraMadrona.jpg?width=1280', 'Javier martin (Public domain) · Wikimedia Commons', NULL, NULL, 1, NULL, 4, '{"categoria":"Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)","ambito":"autonómico","origen":"regionalStatus del park.json"}', 1, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (3 hábitats; barrido de 2026-08-17); EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Malvales', 'Cistaceae', 'Helianthemum', 'No evaluada en la Lista Roja mundial de la UICN', 'EN — En peligro (Lista Roja española, 2010)', 'UICN España: EN (En peligro) (2010)', 'Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', 'Región de Murcia', NULL, 5102, 8148601, 1, NULL, NULL, NULL
