    SELECT 'Lagartija colilarga', 'Psammodromus algirus', 'fauna', 'Reptil', 'Matorral litoral y laderas secas', 'Lagartija esbelta de escamas grandes, quilladas y brillantes, con dos líneas claras muy marcadas a cada lado del dorso. La cola puede medir el doble que el cuerpo. Los machos lucen en primavera manchas azules en el hombro y las mejillas anaranjadas.', NULL, 'Dos líneas claras nítidas a lo largo de cada costado; Escamas grandes y quilladas, de aspecto brillante; Cola larguísima, hasta el doble que el cuerpo', 'Primavera a otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Psammodromus_algirus_-_01.jpg?width=1280', 'Carlos Delgado (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (3 hábitats; barrido de 2026-08-17); Decreto n.º 259/2019, de 10 de octubre, Plan de gestión integral del Mar Menor y la franja litoral mediterránea, volumen II §1.1.5.2 (ZEC «Cabezo Gordo», ES6200013) (BORM n.º 242, de 19 de octubre de 2019): la norma la enumera en la ZEC «Cabezo Gordo» (ES6200013), 229,46 ha, sobre las 271,8 ha del Paisaje Protegido. El propio plan hace suyo ese inventario para el Paisaje Protegido —su §2.2.2 remite al §1.1.5 «y, por tanto, el Paisaje Protegido “Cabezo Gordo”»—, pero el perímetro inventariado es el de la ZEC, no el del espacio; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Reptilia', 'Squamata', 'Lacertidae', 'Psammodromus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2009)', 'LC — Preocupación menor (Lista Roja española, 2002)', 'LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Región de Murcia', NULL, 10670, 2469763, 1, NULL, NULL, NULL
    UNION ALL
    SELECT 'Rabogato', 'Sideritis pusilla', 'flora', 'Mata', 'Vive en matorrales y tomillares sobre sustratos básicos, hasta 1000 m', 'Sufrútice de 17-42 cm, tallos con pelos muy abundantes, cortos dirigidos hacia abajo y y largos más o menos perpendiculares o dirigidos hacia arriba cubriéndolos totalmente; hojas de 8-17 x 1-6 mm, lanceoladas, mucronadas, con uno a tres dientes a cada lado, con pelos largos; inflorescencia en verticilastros con seis flores cada uno, brácteas de 4-15 x 8-10 mm, ovadas, anchas, con seis o siete dientes a cada lado, muy pelosas; cáliz de 6-8,5 mm, con cinco dientes de 2-3,5 mm; corola de 8-9 mm, de color blanco o crema.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Febrero a julio', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sideritis_pusilla0592.jpg?width=1280', 'Nanosanchez (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)","ambito":"autonómico","origen":"regionalStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (3 hábitats; barrido de 2026-08-17); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; Decreto n.º 259/2019, de 10 de octubre, Plan de gestión integral del Mar Menor y la franja litoral mediterránea, volumen II §1.1.5.2 (ZEC «Cabezo Gordo», ES6200013) (BORM n.º 242, de 19 de octubre de 2019): la norma la enumera en la ZEC «Cabezo Gordo» (ES6200013), 229,46 ha, sobre las 271,8 ha del Paisaje Protegido. El propio plan hace suyo ese inventario para el Paisaje Protegido —su §2.2.2 remite al §1.1.5 «y, por tanto, el Paisaje Protegido “Cabezo Gordo”»—, pero el perímetro inventariado es el de la ZEC, no el del espacio, que la cita como «Sideritis pusilla subsp. carthaginensis»; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Lamiaceae', 'Sideritis', 'No evaluada en la Lista Roja mundial de la UICN', 'VU — Vulnerable (Lista Roja española, 2000)', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', 'Región de Murcia', NULL, 8348, 7307458, 1, NULL, NULL, NULL
