-- ------------------------------------------------------------------------------------------------
-- 4. Vínculos especie↔hábitat (22). `evidence` = lo que declara el `source` de cada ficha; ver cabecera.
-- ------------------------------------------------------------------------------------------------
INSERT INTO species_habitats (species_id, habitat_id, evidence)
SELECT sp.id, hb.id, v.evidence
FROM parks pk
JOIN (
    SELECT 'Periploca angustifolia' scientific_name, 'matorrales-arborescentes-de-5220' habitat_slug, 'caracteristica' evidence
    UNION ALL
    SELECT 'Periploca angustifolia', 'matorrales-termomediterraneos-y-5330', 'observada_gbif'
    UNION ALL
    SELECT 'Periploca angustifolia', 'pendientes-rocosas-calcicolas-8210', 'observada_gbif'
    UNION ALL
    SELECT 'Cosentinia vellea', 'matorrales-arborescentes-de-5220', 'observada_gbif'
    UNION ALL
    SELECT 'Cosentinia vellea', 'matorrales-termomediterraneos-y-5330', 'observada_gbif'
    UNION ALL
    SELECT 'Cosentinia vellea', 'pendientes-rocosas-calcicolas-8210', 'caracteristica'
    UNION ALL
    SELECT 'Helianthemum violaceum', 'matorrales-arborescentes-de-5220', 'observada_gbif'
    UNION ALL
    SELECT 'Helianthemum violaceum', 'matorrales-termomediterraneos-y-5330', 'observada_gbif'
    UNION ALL
    SELECT 'Helianthemum violaceum', 'pendientes-rocosas-calcicolas-8210', 'observada_gbif'
    UNION ALL
    SELECT 'Polygala rupestris', 'matorrales-arborescentes-de-5220', 'observada_gbif'
    UNION ALL
    SELECT 'Polygala rupestris', 'matorrales-termomediterraneos-y-5330', 'observada_gbif'
    UNION ALL
    SELECT 'Polygala rupestris', 'pendientes-rocosas-calcicolas-8210', 'observada_gbif'
    UNION ALL
    SELECT 'Psammodromus algirus', 'matorrales-arborescentes-de-5220', 'observada_gbif'
    UNION ALL
    SELECT 'Psammodromus algirus', 'matorrales-termomediterraneos-y-5330', 'observada_gbif'
    UNION ALL
    SELECT 'Psammodromus algirus', 'pendientes-rocosas-calcicolas-8210', 'observada_gbif'
    UNION ALL
    SELECT 'Sideritis pusilla', 'matorrales-arborescentes-de-5220', 'observada_gbif'
    UNION ALL
    SELECT 'Sideritis pusilla', 'matorrales-termomediterraneos-y-5330', 'caracteristica'
    UNION ALL
    SELECT 'Sideritis pusilla', 'pendientes-rocosas-calcicolas-8210', 'observada_gbif'
    UNION ALL
    SELECT 'Teucrium carolipaui', 'matorrales-arborescentes-de-5220', 'observada_gbif'
    UNION ALL
    SELECT 'Teucrium carolipaui', 'matorrales-termomediterraneos-y-5330', 'caracteristica'
    UNION ALL
    SELECT 'Teucrium carolipaui', 'pendientes-rocosas-calcicolas-8210', 'observada_gbif'
    UNION ALL
    SELECT 'Centaurea saxicola', 'pendientes-rocosas-calcicolas-8210', 'caracteristica'
) v
JOIN species sp ON sp.park_id = pk.id AND sp.scientific_name = v.scientific_name
JOIN habitats hb ON hb.park_id = pk.id AND hb.slug = v.habitat_slug
WHERE pk.slug = 'cabezo-gordo'
ON DUPLICATE KEY UPDATE evidence = VALUES(evidence);

-- ------------------------------------------------------------------------------------------------
-- 5. Comprobación posterior. Debe devolver exactamente los recuentos de la cabecera.
-- ------------------------------------------------------------------------------------------------
SELECT
    (SELECT COUNT(*) FROM parks WHERE slug = 'cabezo-gordo') AS espacio,
    (SELECT COUNT(*) FROM habitats h JOIN parks p ON p.id = h.park_id WHERE p.slug = 'cabezo-gordo') AS habitats,
    (SELECT COUNT(*) FROM species s JOIN parks p ON p.id = s.park_id WHERE p.slug = 'cabezo-gordo') AS especies,
    (SELECT COUNT(*) FROM species_habitats sh JOIN species s ON s.id = sh.species_id JOIN parks p ON p.id = s.park_id WHERE p.slug = 'cabezo-gordo') AS vinculos;
